const char str_0810A5B4[] = "  Toy Flower";
const char str_0810A5C4[] = "Summer:";
const char str_0810A5CC[] = "  Tomato";
const char str_0810A5D8[] = "  Corn";
const char str_0810A5E0[] = "  Pumpkin";
const char str_0810A5EC[] = "  Pineapple";
const char str_0810A5F8[] = "  Onion";
const char str_0810A600[] = "  Pink Cat Grass";
const char str_0810A614[] = "Fall";
const char str_0810A61C[] = "  Eggplant";
const char str_0810A628[] = "  Pepper";
const char str_0810A634[] = "  Carrot";
const char str_0810A640[] = "  Spinach";
const char str_0810A64C[] = "  Magic Grass";
const char str_0810A65C[] = "Winter";
const char str_0810A664[] = "  Nothing";
const char str_0810A670[] = "Your crops will grow well";
const char str_0810A68C[] = "if you give them water after";
const char str_0810A6AC[] = "planting. Watering them";
const char str_0810A6C4[] = "more than once a day";
const char str_0810A6DC[] = "has no effect.";
const char str_0810A6EC[] = "When your crops ripen,";
const char str_0810A704[] = "they are ready to be ";
const char str_0810A71C[] = "harvested. Each crop ripens";
const char str_0810A738[] = "at a different rate. ";
const char str_0810A750[] = "Some crops will disappear";
const char str_0810A76C[] = "entirely once you harvest";
const char str_0810A788[] = "them, but others will";
const char str_0810A7A0[] = "ripen again if you just";
const char str_0810A7B8[] = "give them water.";
