const char str_0836F498[] = "RIFF";
const char str_0836F4A0[] = "SCR CODE";
const char str_0836F538[] = "STR :";
const char str_0836F548[] = "You'll be able to catch lots\r\nof fish with that!\x05";
const char str_0836F57C[] = "RIFF";
const char str_0836F584[] = "SCR CODE";
const char str_0836F61C[] = "STR .";
const char str_0836F62C[] = "You've gotten a nice \r\nfishing rod. \x05";
