const char str_083D0C92[] = "Hi.\x05";
const char str_083D0C97[] = "Ann's watching the store \r\nfor me, but I'm worried \r\nabout her alone...\x05";
const char str_083D0CE0[] = "A year passes pretty\r\nquick around here, doesn't\r\nit, ";
const char str_083D0D1F[] = "Don't you ever miss \r\nanybody, ";
const char str_083D0D44[] = "RIFF";
const char str_083D0D4C[] = "SCR CODE";
const char str_083D5BD8[] = "JUMPL\n";
const char str_083D662C[] = "STR ";
